import pandas as pd
from pandas import Interval
from pandas.core.arrays.interval import IntervalArray


def summarize(obj):
    # Safely extract dtype-like attributes
    d = getattr(obj, 'dtype', None)
    # Try common nested dtype fields
    subtype = None
    try:
        subtype = getattr(d, 'subtype', None)
    except Exception:
        subtype = 'err'
    right = getattr(obj, 'right', None)
    length = getattr(obj, 'length', None)
    right_dtype = getattr(right, 'dtype', None) if right is not None else None
    length_dtype = getattr(length, 'dtype', None) if length is not None else None
    return {
        'dtype': str(d),
        'dtype_subtype': str(subtype),
        'right_dtype': str(right_dtype),
        'length_dtype': str(length_dtype),
    }

results = {}

# Right-overflow example
try:
    arr = IntervalArray([Interval(0, 2**64)])
    results['IntervalArray([Interval(0, 2**64)])'] = {'outcome':'success', **summarize(arr)}
except TypeError as e:
    results['IntervalArray([Interval(0, 2**64)])'] = {'outcome':'TypeError', 'msg': str(e)}

# IntervalIndex.from_arrays right-overflow
try:
    idx = pd.IntervalIndex.from_arrays([0], [2**64])
    results['IntervalIndex.from_arrays([0], [2**64])'] = {'outcome':'success', **summarize(idx)}
except TypeError as e:
    results['IntervalIndex.from_arrays([0], [2**64])'] = {'outcome':'TypeError', 'msg': str(e)}

# Left-overflow mirror cases (expected to be TypeError even on buggy)
try:
    idx2 = pd.IntervalIndex.from_arrays([-(2**64)], [0])
    results['IntervalIndex.from_arrays([-(2**64)], [0])'] = {'outcome':'success', **summarize(idx2)}
except TypeError as e:
    results['IntervalIndex.from_arrays([-(2**64)], [0])'] = {'outcome':'TypeError', 'msg': str(e)}

try:
    arr2 = IntervalArray([Interval(-(2**64), 0)])
    results['IntervalArray([Interval(-(2**64), 0)])'] = {'outcome':'success', **summarize(arr2)}
except TypeError as e:
    results['IntervalArray([Interval(-(2**64), 0)])'] = {'outcome':'TypeError', 'msg': str(e)}

probe(results)

